  (function(){
    var nav=document.querySelector('.nav'),burger=document.getElementById('navBurger'),menu=document.getElementById('mobileMenu'),lastY=0;
    if(burger&&menu){
      burger.addEventListener('click',function(){
        var open=menu.classList.toggle('is-open');
        burger.classList.toggle('is-open',open);
        burger.setAttribute('aria-expanded',open);
        menu.setAttribute('aria-hidden',!open);
        document.body.style.overflow=open?'hidden':'';
      });
      menu.querySelectorAll('a').forEach(function(a){
        a.addEventListener('click',function(){
          menu.classList.remove('is-open');burger.classList.remove('is-open');
          burger.setAttribute('aria-expanded','false');menu.setAttribute('aria-hidden','true');
          document.body.style.overflow='';
        });
      });
    }
    window.addEventListener('scroll',function(){
      var y=window.pageYOffset;
      if(menu&&menu.classList.contains('is-open'))return;
      if(y>60&&y>lastY){nav.style.transform='translateY(-100%)';}else{nav.style.transform='';}
      lastY=y;
    },{passive:true});
  })();
